def page(title,body,path='',description='',extra=''):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><meta name="robots" content="noindex,nofollow"><link rel="canonical" href="{ORIGIN}/{path.lstrip('/')}"><link rel="icon" href="{link('img/favicon.png')}"><link rel="preload" href="{link('assets/source-sans.woff2')}" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="{link('assets/site.css')}">{extra}</head><body>{header()}<main id="main">{body}</main>{footer()}</body></html>'''
